        "[general.list_highlight_inactive]", "fg = "Black"", "bg = "LightBlue"",
        "[journals_list.block_active]", "fg = "Reset"", "bg = """,
        "[journals_list.block_inactive]", "fg = "#AAAAC8"", "bg = """,
        "[journals_list.block_multi_select]", "fg = "Yellow"", "bg = """,
        "[journals_list.highlight_active]", "fg = "Black"", "bg = "LightGreen"",
        "[journals_list.highlight_inactive]", "fg = "Black"", "bg = "LightBlue"",
        "[journals_list.title_active]", "fg = "Reset"", "bg = """,
        "[journals_list.title_inactive]", "fg = "#AAAAC8"", "bg = """,
        "[journals_list.title_selected]", "fg = "Yellow"", "bg = """,
        "[journals_list.date_priority]", "fg = "LightBlue"", "bg = """,
        "[journals_list.tags_default]", "fg = "LightCyan"", "bg = """,
        "[editor.block_insert]", "fg = "LightGreen"", "bg = """,
        "[editor.block_visual]", "fg = "Blue"", "bg = """,
        "[editor.block_normal_active]", "fg = "Reset"", "bg = """,
        "[editor.block_normal_inactive]", "fg = "#AAAAC8"", "bg = """,
        "[editor.cursor_normal]", "fg = "Black"", "bg = "White"",
        "[editor.cursor_insert]", "fg = "Black"", "bg = "LightGreen"",
        "[editor.cursor_visual]", "fg = "Black"", "bg = "Blue"",
        "[editor.selection_style]", "fg = "Black"", "bg = "White"",
        "[msgbox]", "error = "LightRed"", "warning = "Yellow"",
        "[msgbox]", "info = "LightGreen"", "question = "LightBlue"",
    };

    int num_themes = sizeof(themes) / sizeof(themes[0]);
    char home[256];
    if (getenv("HOME") != NULL) {
        strncpy(home, getenv("HOME"), sizeof(home) - 1);
        home[sizeof(home) - 1] = '\0';
    } else {
        strncpy(home, DEFAULT_HOME, sizeof(home) - 1);
        home[sizeof(home) - 1] = '\0';
    }

    char themes_path[512];
    snprintf(themes_path, sizeof(themes_path), "%s/.config/tui-journal/themes.toml", home);

    // Create directory if it doesn't exist
    char dir_path[512];
    strncpy(dir_path, themes_path, sizeof(dir_path) - 1);
    dir_path[sizeof(dir_path) - 1] = '\0';
    char *last_slash = strrchr(dir_path, '/');
    if (last_slash != NULL) {
        *last_slash = '\0';
        mkdir(dir_path, 0755);
    }

    FILE *fp = fopen(themes_path, "w");
    if (fp == NULL) {
        perror("Failed to write themes file");
        return;
    }

    for (int i = 0; i < num_themes; i++) {
        if (i > 0 && i % 3 == 0) {
            fprintf(fp, "\n");
        }
        fprintf(fp, "%s", themes[i * 3]);
        if (themes[i * 3 + 1][0] != '\0') {
            fprintf(fp, "\n");
            fprintf(fp, "%s", themes[i * 3 + 1]);
        }
        if (themes[i * 3 + 2][0] != '\0') {
            fprintf(fp, "\n");
            fprintf(fp, "%s", themes[i * 3 + 2]);
        }
    }
    fprintf(fp, "\n");
    fclose(fp);

    printf("Default themes written to: %s\n", themes_path);
}
