        return;
    }

    match cli.command {
        Some(Commands::PrintConfig) => print_config(),
        Some(Commands::ImportJournals { path }) => {
            println!("Importing journals from: {}", path.display());
        }
        Some(Commands::AssignPriority { priority }) => {
            println!("Assigning priority: {}", priority);
